 byte[] annex(byte[] b)throws Exception{if(b.length>=4&&b[0]==0&&b[1]==0&&(b[2]==1||(b[2]==0&&b[3]==1)))return b;ByteArrayOutputStream o=new ByteArrayOutputStream();for(int p=0;p+4<=b.length;){int n=ByteBuffer.wrap(b,p,4).getInt();p+=4;if(n<=0||p+n>b.length)throw new IOException("NAL length");o.write(new byte[]{0,0,0,1});o.write(b,p,n);p+=n;}return o.toByteArray();}
 void replay(String file)throws Exception{MediaExtractor e=new MediaExtractor();try{File fixture=new File(getTargetContext().getCacheDir(),file);try(InputStream in=new ParcelFileDescriptor.AutoCloseInputStream(getUiAutomation().executeShellCommand("cat /sdcard/"+file));FileOutputStream out=new FileOutputStream(fixture)){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}try(FileInputStream in=new FileInputStream(fixture)){e.setDataSource(in.getFD());}int track=0;for(;track<e.getTrackCount();track++)if(e.getTrackFormat(track).getString("mime").startsWith("video/"))break;e.selectTrack(track);MediaFormat f=e.getTrackFormat(track);int w=f.getInteger("width"),h=f.getInteger("height");service.getClass().getMethod("onVideoSize",float.class,float.class,float.class,float.class).invoke(service,(float)w,(float)h,(float)w,(float)h);ByteArrayOutputStream csd=new ByteArrayOutputStream();for(String key:new String[]{"csd-0","csd-1"})if(f.containsKey(key))csd.write(bytes(f.getByteBuffer(key)));ByteBuffer sample=ByteBuffer.allocate(4000000);boolean first=true;for(int i=0;i<25;i++){sample.clear();int n=e.readSampleData(sample,0);if(n<0)break;byte[] raw=new byte[n];sample.position(0);sample.get(raw);byte[] frame=annex(raw);if(first){ByteArrayOutputStream joined=new ByteArrayOutputStream();joined.write(csd.toByteArray());joined.write(frame);frame=joined.toByteArray();first=false;}service.getClass().getMethod("onVideoData",byte[].class,long.class,boolean.class).invoke(service,frame,System.nanoTime(),false);Thread.sleep(30);e.advance();}}finally{e.release();}Thread.sleep(100);}
